create table sys_timezone
(
    id           bigint auto_increment comment '主键ID'
        primary key,
    utc_value    varchar(124)                        null comment 'UTC偏移值',
    abbr         varchar(10)                         null comment '时区缩写',
    offset       decimal(4, 2)                       null comment '时区偏移量',
    offset_value varchar(20)                         null comment '时区偏移值',
    dst          tinyint(1)                          null comment '是否夏令时',
    utc          text                                not null comment 'UTC时区列表',
    created      timestamp default CURRENT_TIMESTAMP null comment '创建时间',
    updated      timestamp default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_general_ci COMMENT = '系统时区表';




-- 渠道类型配置
create table channel_type_config
(
    id            bigint auto_increment comment '主键ID' primary key,
    channel       varchar(20)                         not null comment '渠道号',
    type          varchar(20)                         not null comment '类型，web,gp（对应cds-pg中time_report_channel_conf.type）',
    enable        bigint    default 0                 not null comment '是否启用，0-否，1-是',
    remark        varchar(255)                        null comment '备注',
    created_by_id bigint                              not null comment '创建者ID',
    update_by_id  bigint    default null comment '修改者ID',
    created       timestamp default CURRENT_TIMESTAMP null comment '创建时间',
    updated       timestamp default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_general_ci COMMENT = '渠道类型配置';

ALTER TABLE channel_type_config
    ADD UNIQUE INDEX uniq_channel (channel);

-- 投放方分组配置
create table parent_team_group_config
(
    id             bigint auto_increment comment '主键ID' primary key,
    parent_team_id bigint(20)                          not null comment '投放方id',
    group_keys     varchar(255)                        not null comment '群组（对应cds-pg中time_report_channel_conf.group_key）格式[key1,key2,key3]',
    remark         varchar(255)                        null comment '备注',
    enable         bigint    default 0                 not null comment '是否启用，0-否，1-是',
    created_by_id  bigint                              not null comment '创建者ID',
    update_by_id   bigint    default null comment '修改者ID',
    created        timestamp default CURRENT_TIMESTAMP null comment '创建时间',
    updated        timestamp default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间'
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_general_ci COMMENT = '投放方分组配置';

ALTER TABLE parent_team_group_config
    ADD UNIQUE INDEX uniq_channel (parent_team_id);
